/**
 * CoachPanel — "Learning Corner" for beginner investors.
 *
 * Renders 2–4 jargon-free bullet points generated by the LLM that explain
 * the analysis findings in plain English and suggest what the investor might
 * want to think about next.
 *
 * The panel is collapsible so experienced users can hide it.  A clear
 * educational disclaimer is displayed beneath the bullets.
 */

import { useState } from 'react'

interface CoachPanelProps {
  bullets: string[]
}

export default function CoachPanel({ bullets }: CoachPanelProps) {
  const [open, setOpen] = useState(true)

  if (!bullets || bullets.length === 0) return null

  return (
    <section className="card space-y-3 border-l-4 border-l-violet-400" aria-labelledby="coach-heading">

      {/* ── Header ───────────────────────────────────────────────────────── */}
      <button
        type="button"
        onClick={() => setOpen(o => !o)}
        className="flex w-full items-center justify-between text-left"
        aria-expanded={open}
        aria-controls="coach-body"
      >
        <h2 id="coach-heading" className="section-heading mb-0 flex items-center gap-2">
          <span aria-hidden="true" className="text-base">🎓</span>
          Learning Corner
        </h2>
        <span className="text-xs text-gray-400" aria-hidden="true">
          {open ? '▲ Hide' : '▼ Show'}
        </span>
      </button>

      {/* ── Body ─────────────────────────────────────────────────────────── */}
      {open && (
        <div id="coach-body" className="space-y-3">
          <ul className="space-y-2">
            {bullets.map((bullet, i) => (
              <li key={i} className="flex gap-2 text-sm leading-relaxed text-gray-700">
                <span className="mt-0.5 shrink-0 text-violet-400 font-bold" aria-hidden="true">•</span>
                {bullet}
              </li>
            ))}
          </ul>

          {/* Disclaimer */}
          <p className="rounded-md bg-gray-50 px-3 py-2 text-xs text-gray-500">
            <strong>Educational only.</strong> These bullet points are AI-generated explanations
            of the analysis data above. They are not financial advice and should not be the sole
            basis for any investment decision.
          </p>
        </div>
      )}
    </section>
  )
}
